parameters.jsonBody:
={
  "contents": [{
    "parts": [
      {"text": "Write 3 high-converting social media posts based on this topic: {{$json.body.topic}}. Output a JSON object with keys: linkedin (long-form narrative), twitter_thread (punchy numbered thread), and instagram_caption (visual summary with relevant hashtags)."}
    ]
  }],
  "generationConfig": { "response_mime_type": "application/json" }
}

parameters.jsCode:
const topic = $input.first().json.body?.topic || 'Automation for SMEs';
return [{ json: {
  posts: [
    { platform: 'LinkedIn', content: `${topic}. Most SMEs lose hours to repetitive work. Automate leads, invoices, and follow-ups to scale fast.` },
    { platform: 'X', content: `1/ ${topic}\n2/ Start with tasks repeated daily.\n3/ Connect n8n webhooks.\n4/ Reclaim 10 hours/week.` },
    { platform: 'Instagram', content: `${topic} ✨ Save this post for your next workflow audit. #automation #sme #operations` }
  ]
} }];
